    assert.deepEqual([node.status, node.attempt, node.session_id, node.result_uri], ['succeeded', 1, REVIEWER, '/api/projects/alpha/workflows/main/runs/reviewed/reviews/1'])
    assert.equal(detail.summary.status, 'running')
